const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roles={boss:'老板',manager:'管理',employee:'员工'},permissions={view:'可查看',edit:'可编辑',full:'完全权限'};
const items=[{id:'water',name:'饮用水',unit:'瓶',box:24,pack:6,stock:92,integer:true},{id:'flour',name:'面粉',unit:'kg',box:10,pack:1,stock:18,integer:false}];
let role='boss',permission='full',page='home',task,inventory,events,counts,note='',toastTimer;
function reset(){task={status:'unassigned',assigneeType:'employee',assignee:'阿明',due:'今日 18:00',submitted:null,issue:''};inventory=Object.fromEntries(items.map(i=>[i.id,i.stock]));events=[];counts=Object.fromEntries(items.map(i=>[i.id,{box:'',pack:'',loose:''}]));note='';}
reset();
const editable=()=>permission!=='view',approver=()=>permission==='full'&&role!=='employee';
const total=i=>{const q=counts[i.id];return Math.round((Number(q.box||0)*i.box+Number(q.pack||0)*i.pack+Number(q.loose||0))*1000)/1000;};
const amount=n=>'RM '+n.toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3000);}
function changeRole(value){role=value;permission=role==='boss'?'full':'edit';page='home';render();window.scrollTo(0,0);}
function intro(title,description){return `<div class="intro"><div><div class="eyebrow">${roles[role]}工作空间</div><h1>${title}</h1><p>${description}</p></div><span class="pill">${permissions[permission]} · 演示权限</span></div>`;}
function permissionNote(action){return `<div class="permission-note">当前为「${permissions[permission]}」。${action||'本页仅模拟界面权限，未实施真实身份或后台授权。'}</div>`;}
function boss(){return intro('生意怎么样？','销售截至 10月18日结算；今日尚未结算。以下均为演示数据。')+`<div class="boss-top"><section class="card hero-sales"><div class="hero-top"><small>最近已结算 · 10月18日</small><span class="pill">已结算</span></div><div class="hero-number"><span class="currency">RM</span>11,280.00</div><div class="trend-up">↑ 6.0%　较上周同日增加 RM640</div><div class="mini-metrics"><div><small>订单数</small><b>268 单</b></div><div><small>平均每单</small><b>RM42.09</b></div><div><small>今日数据</small><b>待结算</b></div></div></section><section class="card decision-card"><div class="hero-top"><h3>本月先留意这两件事</h3><span class="pill amber">需留意</span></div><div class="decision-row"><b>食材成本率接近目标上限</b>暂估 33.8%，演示目标上限 35%。先核查耗用与库存差异，再决定是否调整。</div><div class="decision-row"><b>成本资料还未齐全</b>有 2 笔演示账单待确认，经营利润暂估；不能作为最终月结利润。</div><button class="link" data-action="finance">展开经营明细 →</button></section></div><div class="section-head"><h2>本月经营进度</h2><small>10月1日–18日 · 演示</small></div><div class="kpi-grid"><article class="card"><small>累计营业额</small><b>184,600</b><p>MYR · 最近结算累计</p></article><article class="card"><small>食材成本率 · 暂估</small><b>33.8<span style="font-size:14px">%</span></b><div class="progress"><i style="width:96.5%"></i></div><p>COGS RM62,400 / 目标 ≤35%</p></article><article class="card"><small>人工成本率 · 暂估</small><b>22.6<span style="font-size:14px">%</span></b><div class="progress"><i style="width:90.4%"></i></div><p>已发生 RM41,800 / 目标 ≤25%</p></article><article class="card"><small>经营利润 · 暂估</small><b>55,100</b><p>尚有费用待确认，非最终利润</p></article></div><div class="lower-grid"><section class="card"><div class="hero-top"><h2>最近 7 天营业</h2><span class="pill gray">图表示意</span></div><div class="chart" aria-label="7天演示营业额：12日8800，13日9700，14日10500，15日9200，16日10100，17日12200，18日11280">${[8800,9700,10500,9200,10100,12200,11280].map((n,i)=>`<div class="bar-column"><i style="height:${n/130}px" title="${amount(n)}"></i><span>${i+12}日</span></div>`).join('')}</div><p>点击「经营明细」查看成本组成和资料状态。</p><div class="actions"><button data-action="finance">经营明细</button><button data-action="catalog">检查其他模块 →</button></div></section><section class="card desktop-only">${financeTable()}</section></div><div class="read-note">数据口径：营业额取已结算记录；COGS 按耗用口径，不能直接等同采购金额；人工包含本月已发生但未发薪部分。所有金额为界面演示。</div>`;}
function financeTable(){return `<h2>本月经营组成</h2><table class="detail-table"><thead><tr><th>项目</th><th>金额 / RM</th><th>资料状态</th></tr></thead><tbody><tr><td>已结算营业额</td><td>184,600</td><td>演示已确认</td></tr><tr><td>食材耗用 COGS</td><td>62,400</td><td>暂估</td></tr><tr><td>人工成本</td><td>41,800</td><td>暂估</td></tr><tr><td>其他营运费用</td><td>25,300</td><td>有待补资料</td></tr><tr><td><b>经营利润</b></td><td><b>55,100</b></td><td>暂估</td></tr></tbody></table><p style="margin-top:14px">预估利润 = 营业额 − COGS − 人工 − 其他费用。待确认项目不隐藏。</p>`;}
function statusLabel(){return {unassigned:'尚未指派',assigned:'待处理',progress:'进行中',submitted:'待管理确认',returned:'需补充',confirmed:'已完成',issue:'需要协助'}[task.status];}
function countTask(){return `<article class="task"><div class="task-counter">▤</div><div class="task-text"><span class="pill ${task.status==='submitted'?'amber':task.status==='confirmed'?'':'gray'}">${statusLabel()}</span><h3>点算仓库饮用水与面粉</h3><p>${task.status==='unassigned'?'先指派给员工或岗位':esc(task.assignee)+' · '+esc(task.due)} · 2 项材料</p></div><button data-action="${task.status==='unassigned'?'assign':role==='employee'?'count':'review'}">${task.status==='unassigned'?'指派任务':role==='employee'?'打开':'查看'}</button></article>`;}
function manager(){return intro('今天的工作','先处理待办，再安排员工工作。管理角色演示。')+`<section class="card"><div class="hero-top"><h2>需要先处理</h2><span class="pill amber">演示待办</span></div>${countTask()}<article class="task"><div class="task-counter">◷</div><div class="task-text"><span class="pill gray">待操作</span><h3>今日每日结算</h3><p>10月19日 · 营业额待结算后更新</p></div><button data-module="每日结算">进入</button></article><article class="task"><div class="task-counter">▱</div><div class="task-text"><span class="pill gray">待收货</span><h3>核对今日到货</h3><p>收货流程入口示意，未连接真实采购单</p></div><button data-module="收货核对">查看</button></article></section><div class="section-head"><h2>常用操作</h2><button class="link" data-action="catalog">全部功能 →</button></div><div class="quick-grid">${[['每日结算','▥'],['采购订货','▱'],['收货核对','✓'],['排班安排','▦']].map(([n,i])=>`<button data-module="${n}"><span class="icon">${i}</span>${n}</button>`).join('')}</div><div class="section-head"><h2>员工工作安排</h2><button class="link" data-action="assign" ${!editable()?'disabled':''}>＋ 安排任务</button></div><section class="card"><p>可按员工或岗位指派。重点任务提交后由拥有完全权限的人确认。</p>${countTask()}<div class="actions"><button data-action="assign" ${!editable()?'disabled':''}>安排盘点任务</button><button data-action="review">查看盘点与库存</button></div></section>${permissionNote(permission==='view'?'可以查看任务；不能指派、修改或确认。':permission==='edit'?'可以安排任务；确认更新库存需切换为「完全权限」。':'可安排任务，并可确认员工已提交的盘点。')}`;}
function employee(){return intro('阿明，今天做什么？','仓库协助岗位 · 演示员工 · 沿用员工 ID 登录的界面方向')+`<section class="card"><div class="hero-top"><h2>管理交办</h2><span class="pill gray">${task.status==='unassigned'?'0':'1'} 个盘点任务</span></div>${task.status==='unassigned'?'<div class="empty">还没有收到盘点任务。<br>在上方切换到「管理」，先安排一次任务。</div>':countTask()}</section><div class="section-head"><h2>我的岗位指引</h2><small>无需评分</small></div><section class="card routine"><p>每天应该怎么做，按岗位查看；不设评分，也不逐项审批。</p><details><summary>开档准备</summary><p>检查储物区域是否整洁；确认通道畅通、工具归位；发现异常及时向管理报告。</p></details><details><summary>材料与仓库整理</summary><p>依标示位置存放；检查包装和有效期；遵守先到先用原则。涉及数量调整时使用正式盘点任务。</p></details><details><summary>清洁与收档</summary><p>清洁工作台与外部负责区域；清理垃圾、归位工具；记录未处理的问题，交接给管理。</p></details></section><div class="read-note">遇到缺货、无法维修或无法点算时，报「需要协助」即可，不要随意填写一个数量。</div>${permissionNote(permission==='view'?'可阅读岗位指引和任务；暂不能填写或提交。':'可填写自己的获派任务；提交后由管理确认，员工不能确认自己的盘点入账。')}`;}
function countPage(){if(task.status==='unassigned')return employee();const submitted=['submitted','confirmed'].includes(task.status);return `<button class="return" data-action="home">← 返回今日工作</button>`+intro('仓库材料盘点','不分营业中或收档；点算一次，系统记录时间。')+`<div class="two-col"><section><section class="card"><div class="task-header"><h2>点算仓库饮用水与面粉</h2><span class="pill ${task.status==='submitted'?'amber':''}">${statusLabel()}</span></div><p style="margin-top:10px">${esc(task.assignee)} · ${esc(task.due)}<br>按已设置的包装规格换算；不知道的数量不要猜。</p><div class="state-steps"><span class="done">收到任务</span>→<span class="${task.status!=='assigned'?'done':''}">开始点算</span>→<span class="${submitted?'done':''}">提交</span>→<span class="${task.status==='confirmed'?'done':''}">管理确认</span></div>${task.issue?`<div class="permission-note">${esc(task.issue)}</div>`:''}${task.status==='assigned'?`<div class="actions"><button class="primary" data-action="start" ${!editable()?'disabled':''}>开始点算</button></div>`:''}</section>${items.map(i=>`<section class="count-item"><h3>${i.name}</h3><p class="spec">1 箱 = ${i.box} ${i.unit}；1 包 = ${i.pack} ${i.unit}<br>此处「箱」和「包」分开计数，不重复计算整箱里的包。</p><div class="quantity-grid">${[['box','整箱',1],['pack','零包',1],['loose','散装 '+i.unit,i.integer?1:.01]].map(([k,label,step])=>`<label>${label}<input aria-label="${i.name}${label}" inputmode="${step===1?'numeric':'decimal'}" type="number" min="0" step="${step}" data-item="${i.id}" data-unit="${k}" value="${esc(counts[i.id][k])}" ${!editable()||submitted||task.status==='assigned'?'disabled':''}></label>`).join('')}</div><div class="converted"><span>自动换算合计</span><strong id="total-${i.id}">${total(i)} ${i.unit}</strong></div><small id="formula-${i.id}">${counts[i.id].box||0} × ${i.box} + ${counts[i.id].pack||0} × ${i.pack} + ${counts[i.id].loose||0}</small></section>`).join('')}<label class="field">点算备注<textarea id="count-note" ${!editable()||submitted||task.status==='assigned'?'disabled':''} placeholder="例如包装破损、数量异常">${esc(note)}</textarea></label><div id="count-error" class="form-error" role="alert"></div><div class="actions">${!submitted?`<button class="primary" data-action="submit-count" ${!editable()||task.status==='assigned'?'disabled':''}>提交管理确认</button><button data-action="issue" ${!editable()?'disabled':''}>需要协助</button>`:`<button data-action="home">返回工作台</button>`}</div>${submitted?`<div class="read-note">${task.status==='confirmed'?'管理已确认，演示库存已更新。':'已提交，演示库存尚未更新；请切换管理查看确认页。'}</div>`:''}</section><aside class="card"><h2>怎样填最快</h2><div class="helper-steps">例如饮用水：<br>2 箱 + 3 包 + 5 瓶<br>= 2 × 24 + 3 × 6 + 5<br>= <b>71 瓶</b></div><p>面粉支持小数：1 箱 + 2 包 + 0.5 kg = 12.5 kg。包装关系为本稿演示设定，不代表实际商品规格。</p><div class="read-note">没有包装规格时，正式系统应提示补齐，不能默认换算。本稿仅演示已配置商品。</div></aside></div>`;}
function reviewPage(){const ready=task.status==='submitted',done=task.status==='confirmed';return `<button class="return" data-action="home">← 返回工作台</button>`+intro('盘点确认与库存','员工提交后先核对差异，确认时更新库存。全部为本地模拟。')+`<div class="two-col"><section class="card"><div class="hero-top"><h2>仓库材料点算</h2><span class="pill ${ready?'amber':''}">${statusLabel()}</span></div><p style="margin-top:12px">${task.status==='unassigned'?'任务尚未指派':esc(task.assignee)+' · '+esc(task.due)}</p>${task.submitted?`<p>点算提交时间：${esc(task.submitted)}</p>`:''}<table class="detail-table"><thead><tr><th>材料</th><th>当前账面</th><th>实盘</th><th>差异</th></tr></thead><tbody>${items.map(i=>`<tr><td>${i.name}<br><small>${i.unit}</small></td><td>${inventory[i.id]}</td><td>${task.submitted?total(i):'—'}</td><td>${task.submitted?((total(i)-inventory[i.id])>0?'+':'')+Math.round((total(i)-inventory[i.id])*1000)/1000:'—'}</td></tr>`).join('')}</tbody></table>${task.submitted?`<div class="read-note">点算后变动：本演示没有收货或领料变动。正式系统若发现期间变动，必须核对后再确认，不能直接覆盖。</div>`:''}${note?`<p style="margin-top:16px">员工备注：${esc(note)}</p>`:''}${done?`<div class="result"><h3>已确认，演示库存已更新</h3><p>确认前后数量已保留在下方记录中。重复点击不会再次更新。</p></div>`:permissionNote(ready?'只有管理或老板且拥有本模块「完全权限」才能确认更新。':'先安排任务，再切换员工填写并提交，才可确认。')}<div class="actions"><button class="primary" data-action="confirm-count" ${!ready||!approver()?'disabled':''}>确认并更新演示库存</button><button data-action="return-count" ${!ready||!approver()?'disabled':''}>退回补充</button>${task.status==='unassigned'?`<button data-action="assign" ${!editable()?'disabled':''}>安排盘点任务</button>`:''}</div><div id="confirm-error" class="form-error"></div></section><aside class="card"><h2>库存调整记录</h2>${events.length?events.map(e=>`<div class="audit"><b>${esc(e.time)} · ${esc(e.actor)}</b><br>${esc(e.text)}</div>`).join(''):'<div class="empty">尚无确认或库存调整。<br>单纯提交不会更新库存。</div>'}<div class="read-note">演示操作仅在当前页面内存里保存。刷新或重置会清空，不产生真实库存单据。</div></aside></div>`;}
function catalog(){return intro('找其他功能','新版三个首页之外，保留完整功能目录。')+`<section class="card"><h2>完整模块目录</h2><p style="margin-top:12px">目录仍可搜索和收藏。此处仅用于导航与视觉验收。</p><div class="actions"><a class="primary" style="padding:12px 16px;border-radius:9px;font-size:12px" href="modules.html">打开 33 个功能入口 →</a></div></section><div class="section-head"><h2>本稿已串起的流程</h2></div><div class="quick-grid"><button data-action="home"><span class="icon">⌂</span>角色首页</button><button data-action="assign" ${!editable()||role==='employee'?'disabled':''}><span class="icon">＋</span>安排盘点任务</button><button data-action="count" ${task.status==='unassigned'?'disabled':''}><span class="icon">▤</span>填写盘点</button><button data-action="review"><span class="icon">✓</span>确认与库存</button></div>`;}
function render(){document.body.dataset.role=role;document.body.dataset.page=page;const captions={boss:'经营概况',manager:'当班工作台',employee:'我的今日工作'};$('#role-caption').textContent=captions[role];$('#role-select').value=role;$('#permission-select').value=permission;const tabs=role==='boss'?[['home','◴','经营概况'],['finance','▥','经营明细'],['catalog','▦','全部功能']]:role==='manager'?[['home','⌂','工作台'],['review','✓','盘点确认'],['catalog','▦','全部功能']]:[['home','⌂','今日工作'],['count','▤','盘点任务'],['guide','☷','岗位指引']];const nav=tabs.map(([id,icon,title])=>`<button data-page="${id}" class="${page===id?'active':''}" ${id==='count'&&task.status==='unassigned'?'disabled':''}><span>${icon}</span>${title}</button>`).join('');$('#side-nav').innerHTML=nav;$('#mobile-nav').innerHTML=nav;let html=page==='count'?countPage():page==='review'?reviewPage():page==='finance'?intro('经营明细','同一套数据，电脑展开更多；所有数值为演示。')+`<section class="card">${financeTable()}</section>`:page==='catalog'?catalog():role==='boss'?boss():role==='manager'?manager():employee();$('#main').innerHTML=html+`<p class="role-help">角色切换与权限选择仅供设计验收，不能代表真实授权。此稿不连接 ERP、Firebase、支付或库存服务。</p>`;if(page==='guide')$('.routine')?.scrollIntoView({block:'start'});}
function go(value){page=value;render();window.scrollTo(0,0);}
function showModal(html){$('#modal').innerHTML=`<div class="dialog-head"><h2>安排盘点任务</h2><button class="close" data-action="close" aria-label="关闭">×</button></div>${html}`;$('#modal').showModal();}
function assign(){if(!editable()||role==='employee'){toast('当前账号不能安排任务');return;}if(task.status!=='unassigned'){toast('此演示只有一个盘点任务；可先重置演示再重新安排');return;}showModal(`<p>选员工或岗位，任务会出现在对应员工首页。</p><label class="field">指派方式<select id="assignee-type"><option value="employee">指定员工</option><option value="position">指定岗位</option></select></label><label class="field">接收对象<select id="assignee-name"><option>阿明</option></select></label><label class="field">完成时间<input id="due" value="今日 18:00" maxlength="40"></label><div class="assign-preview"><b>点算仓库饮用水与面粉</b><br>饮用水 1箱=24瓶、1包=6瓶<br>面粉 1箱=10kg、1包=1kg<br>全部为演示规格</div><div class="dialog-actions"><button data-action="close">取消</button><button class="primary" data-action="save-assignment">指派任务</button></div>`);}
function validateCounts(){for(const i of items){for(const [k,v] of Object.entries(counts[i.id])){if(v===''||!Number.isFinite(Number(v))||Number(v)<0)return '请填写所有数量；没有的填 0。';if((k!=='loose'||i.integer)&&!Number.isInteger(Number(v)))return '整箱、零包和瓶数必须是整数。';}if(total(i)>100000)return '数量过大，请核对。';}return '';}
function time(){return new Date().toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Kuala_Lumpur'});}
document.addEventListener('change',e=>{if(e.target.id==='role-select')changeRole(e.target.value);if(e.target.id==='permission-select'){permission=e.target.value;render();}if(e.target.id==='assignee-type')$('#assignee-name').innerHTML=e.target.value==='position'?'<option>仓库协助岗位（阿明）</option>':'<option>阿明</option>';});
document.addEventListener('input',e=>{if(e.target.dataset.item){counts[e.target.dataset.item][e.target.dataset.unit]=e.target.value;const i=items.find(i=>i.id===e.target.dataset.item);$('#total-'+i.id).textContent=total(i)+' '+i.unit;$('#formula-'+i.id).textContent=(counts[i.id].box||0)+' × '+i.box+' + '+(counts[i.id].pack||0)+' × '+i.pack+' + '+(counts[i.id].loose||0);}if(e.target.id==='count-note')note=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=b.dataset.action;if(b.id==='reset-demo'){reset();go('home');toast('演示已重置');return;}if(b.dataset.page){go(b.dataset.page);return;}if(b.dataset.module){$('#modal').innerHTML=`<div class="dialog-head"><h2>${esc(b.dataset.module)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><p>当前为「${permissions[permission]}」。这一业务模块尚未在本稿实现；将沿用现有 ERP 功能与后台权限，不在演示中产生真实单据。</p><div class="dialog-actions"><button data-action="close">返回</button></div>`;$('#modal').showModal();return;}if(a==='close')$('#modal').close();if(['home','finance','catalog','review','count'].includes(a))go(a);if(a==='assign')assign();if(a==='save-assignment'&&editable()&&role!=='employee'&&task.status==='unassigned'){task.assigneeType=$('#assignee-type').value;task.assignee=$('#assignee-name').value;task.due=$('#due').value.trim()||'今日内';task.status='assigned';events.push({time:time(),actor:roles[role],text:'已指派盘点给 '+task.assignee});$('#modal').close();go('home');toast('已指派，切换员工即可查看');}if(a==='start'&&editable()&&task.status==='assigned'){task.status='progress';render();toast('可以开始填写数量');}if(a==='submit-count'&&editable()&&['progress','returned','issue'].includes(task.status)){const error=validateCounts();if(error){$('#count-error').textContent=error;return;}task.status='submitted';task.submitted=time();events.push({time:task.submitted,actor:'阿明',text:'提交盘点，库存尚未改变。'});render();toast('已提交，等待管理确认');}if(a==='confirm-count'&&approver()&&task.status==='submitted'){for(const i of items){const before=inventory[i.id];inventory[i.id]=total(i);events.push({time:time(),actor:roles[role]+'（完全权限）',text:i.name+'：'+before+' → '+inventory[i.id]+' '+i.unit+'，依据阿明实盘确认。'});}task.status='confirmed';render();toast('演示库存已更新，已保留前后记录');}if(a==='return-count'&&approver()&&task.status==='submitted'){showModal(`<p>请写明需要员工补充的内容。</p><label class="field">退回原因<textarea id="return-reason" placeholder="例如重新核对面粉散装数量"></textarea></label><div class="dialog-actions"><button data-action="close">取消</button><button class="primary" data-action="save-return">退回补充</button></div>`);$('#modal h2').textContent='退回盘点';}if(a==='save-return'&&approver()&&task.status==='submitted'){const reason=$('#return-reason').value.trim();if(!reason){toast('请填写退回原因');return;}task.status='returned';task.issue='管理退回：'+reason;events.push({time:time(),actor:roles[role],text:task.issue});$('#modal').close();render();}if(a==='issue'&&editable()){showModal(`<p>说明遇到的问题，交给管理跟进。</p><label class="field">问题说明<textarea id="issue-text" placeholder="例如面粉散装无法称重，需要电子秤"></textarea></label><div class="dialog-actions"><button data-action="close">取消</button><button class="primary" data-action="save-issue">告知管理</button></div>`);$('#modal h2').textContent='需要协助';}if(a==='save-issue'&&editable()){const issue=$('#issue-text').value.trim();if(!issue){toast('请先写明问题');return;}task.issue='员工需要协助：'+issue;task.status='issue';events.push({time:time(),actor:'阿明',text:task.issue});$('#modal').close();render();}});
const initialRole=new URLSearchParams(location.search).get('role');if(Object.hasOwn(roles,initialRole)){role=initialRole;permission=role==='boss'?'full':'edit';}render();
